"""Write src/core/document-engine/capture/crop/presenceWeights.ts from an exported PRS1
file and the thresholds chosen by `presence.py eval --json`.

    python3 to_ts.py presence.bin thresholds.json ../../src/core/document-engine/capture/crop/presenceWeights.ts
"""
import base64, json, sys
b, t, out = sys.argv[1:4]
th = json.load(open(t))
open(out, 'w').write(
    '/** Presence gate weights (PRS1, base64) and thresholds — generated by tools/presence; do not edit. */\n'
    f"export const PRESENCE_WEIGHTS_B64 =\n  '{base64.b64encode(open(b, 'rb').read()).decode()}';\n"
    f"export const PRESENCE_THRESHOLDS = {{ present: {th['present']:.6f}, none: {th['none']:.6f} }};\n")
print('wrote', out)
